window.QUESTIONS.push(...[{"id":"112-3-A-1","exam":"112-3","q":1,"unit":"商業概論","topic":"商業概論","stem":"有關商業概念的敘述，下列何者正確？","options":["所謂商業經營的標的物，就廣義而言，是指無形的商品","手工業生產時期屬於產銷分離階段","某咖啡公司向農民保證願意以高價收購有機咖啡豆，以避免因農藥的濫用而破壞生態環境，此一作\n法表示該公司善盡法律責任","大眾願意接受以金屬鑄幣或紙幣等作為交易媒介，以從事商業活動，表示商業的發展為貨幣交易時期"],"answer":"D","official":"(A) 所謂商業經營的標的物，指有形商品和無形服務\n(B) 茅舍生產時期屬於產銷分離階段\n(C) 某咖啡公司向農民保證願意以高價收購有機咖啡\n豆，以避免因農藥的濫用而破壞生態環境，為該公司\n善盡環境保護的社會責任"},{"id":"112-3-A-2","exam":"112-3","q":2,"unit":"商業概論","topic":"商業概論","stem":"有關獨資、有限公司、股份有限公司及閉鎖性股份有限公司的敘述，下列何者正確？","options":["獨資是由個人獨自出資、擁有所有權和經營權、自負盈虧的商業組織","有限公司是由 2 人以上之股東組成的商業組織","股份有限公司不可自由轉讓股權","閉鎖性股份有限公司的股東人數不得低於 50 人"],"answer":"A","official":"(B) 有限公司是由 1 人以上組成的商業組織\n(C) 股份有限公司可自由轉讓股權\n(D) 閉鎖性股份有限公司的股東人數不得「高於」\n50 人"},{"id":"112-3-A-3","exam":"112-3","q":3,"unit":"商業概論","topic":"商業概論","stem":"商業發展依產銷經營的觀點區分，下列敘述何者正確？","options":["在家庭生產時期，生產者大多為專業性的工人，生產技術較為熟練","手工業生產時期亦稱為工廠前身時期","在工廠生產時期，會計制度開始發展","現代化生產時期出現大量的公司組織"],"answer":"D","official":"(A) 在家庭生產時期，生產者主要為家庭中的成員，\n生產技術較不純熟\n(B) 茅舍生產時期亦稱為工廠前身時期\n(C) 會計制度發展於茅舍生產時期"},{"id":"112-3-A-4","exam":"112-3","q":4,"unit":"商業概論","topic":"商業概論","stem":"近年來受到少子化影響，導致大學及高中的招生發生困難，同時也引發了許多學校停止招生與倒閉，根\n據上述，目前學校所遭遇到的風險為何？","options":["法律風險","經營風險","災害風險","市場風險"],"answer":"D","official":"(A) 法律風險：政府政策或法律改變所引起\n(B) 經營風險：為因營運策略失當、錯估市場潛力、\n產銷無法配合、技術不足所引起\n(C) 災害風險：為天災人禍所造成\n(D) 市場風險：少子化會造成市場的衰退"},{"id":"112-3-A-5","exam":"112-3","q":5,"unit":"商業概論","topic":"商業概論","stem":"某知名污水處理場維修人員在地下污水槽處理污水時，因地下沼氣濃度太高導致中毒送醫。請問上述狀\n況符合何種保險的理賠範圍？","options":["公共意外責任險","產品責任險","職業災害保險","人壽保險"],"answer":"C","official":"(A) 公共意外責任險：指因公共場所發生意外事故，\n第三人傷亡或財損的法律責任\n(B) 產品責任險：因產品設計、製造、使用說明不當、\n包裝錯誤出現造成\n(C) 職業災害保險是為了加強保障因工作受傷或生病\n勞工的生活，而辦理的社會保險\n(D) 人壽保險：以人的生命為保險標的"},{"id":"112-3-A-6","exam":"112-3","q":6,"unit":"商業概論","topic":"商業概論","stem":"臺灣知名部落客、有便利商店女神之稱的古娃娃，專門經營美食開箱影片，在 2018 年設立古娃娃娛樂\n有限公司，作為經營其影音頻道之用，更於 2019 年設立米希納股份有限公司，專門經營其自創甜點品\n牌 WA! COOKIES，並推出轉圈圈曲奇餅、古朗尼甜點、雪糕等多款甜點美食。除了透過網路販售的方\n式之外，古娃娃也藉由與各零售通路合作的方式，在全聯、全家、家樂福、大潤發等門市販售雪糕產品，\n由於品牌知名度高、產品品質佳，因此曾創下一年賣出 500 萬支雪糕的佳績。受到 COVID-19 疫情影響，\n網路購物的需求持續增加，在香港、美國等地也擁有廣大知名度的古娃娃，決定拓展國外市場，讓 WA!\nCOOKIES 品牌甜點美食也能宅配到香港、美國，根據上述，其採用了哪一種 SWOT 分析之營運策略擬\n定？","options":["WO 策略","WT 策略","ST 策略","SO 策略"],"answer":"D","official":"在香港、美國擁有知名度和產品品質佳→S(優勢)。網\n路購物需求持續增加→O(機會)"},{"id":"112-3-A-7","exam":"112-3","q":7,"unit":"商業概論","topic":"商業概論","stem":"臺北市政府商業處抽查市售雞蛋，發現有部分標示不合格，因此要求業者限期改善。請問該業者違反何\n種法令的規定？","options":["消費者保護法","公平交易法","商品標示法","公司法"],"answer":"C","official":"(C) 商品標示法用來規定業者於商品本身、內外包裝\n與說明書上標示商品名稱、商品內容、廠商名稱、產\n地、有效日期等"},{"id":"112-3-A-8","exam":"112-3","q":8,"unit":"商業概論","topic":"商業概論","stem":"有關現代化商業機能的敘述，下列何者錯誤？","options":["商流是指商品所有權的移轉過程，且依商品特性，可將其分為開放型商流與選擇型商流","常見的現代金流交易工具有金融卡、信用卡、簽帳卡及預付卡，而上述所有卡片中除金融卡外，其\n餘卡片皆為先消費後付款","高雄小明透過網購向臺北美美購買一幅畫，美美委託宅配公司運送，小明則透過第三方支付付款給\n美美；在此過程中，宅配公司所負責的是消費品物流","運輸配送的功能是屬於物流，而其類型依配送對象區分，又可分為消費品物流與工業品物流"],"answer":"B","official":"(B) 信用卡、簽帳卡為先消費後付款，而預付卡為先\n付款後消費"},{"id":"112-3-A-9","exam":"112-3","q":9,"unit":"商業概論","topic":"商業概論","stem":"選擇金流交易工具時，消費者或業者所考慮的因素不包括下列哪一項？","options":["交易過程須隱密避免曝光，此為隱密性原則","業者須考慮變現速度，有利資金的週轉避免形成呆帳，此為時效性原則","消費者須考慮用卡時不被盜刷，此為安全性原則","消費者選擇交易工具時應知道且完全了解每種工具的特性，此為財務性原則"],"answer":"A","official":"(A) 應該是要公開性，可方便日後查證的原則"},{"id":"112-3-A-10","exam":"112-3","q":10,"unit":"商業概論","topic":"商業概論","stem":"下列各項行業中，屬於有店舖零售業的是哪些？\n①物流中心 ②便利商店 ③代理商 ④網路服飾店 ⑤購物中心 ⑥百貨公司","options":["②⑤","①②③","②⑤⑥","①③④⑤"],"answer":"C","official":"①物流中心：批發業。②便利商店：零售業。③代理\n商：批發業。④網路服飾店：無店舖。⑤購物中心：\n零售業。⑥百貨公司：零售業"},{"id":"112-3-A-11","exam":"112-3","q":11,"unit":"商業概論","topic":"商業概論","stem":"近年來全聯福利中心為了拓展市場，積極發展包括「We Sweet」、「Read Bread」、「Off Coffee」、「美味堂」\n等多個自有品牌、在全臺設置 6 座生鮮和蔬果處理中心、建立「PXGo!全聯線上購」網購平台、推出行\n動支付「PX Pay」及「全支付」，因此深受消費者喜愛，迄今已擁有超過 1,700 萬名會員。從以上敘述\n可推知，全聯福利中心屬於何種零售業？\n①業種店 ②業態店 ③綜合商品零售業 ④專賣零售業 ⑤超商 ⑥超市","options":["①③⑤","①④⑥","②③⑥","②④⑤"],"answer":"C","official":"(D) 全聯福利中心目前屬於業態店、綜合商品零售業\n及超市"},{"id":"112-3-A-12","exam":"112-3","q":12,"unit":"商業概論","topic":"商業概論","stem":"有關網路購物的特性，下列敘述哪些正確？\n①商品展示空間無限延伸\n②若要提升網路購物的發展，須加強網路付款安全機制\n③網路商店是一種虛擬商店，在通路方面無法與實體商店結合\n④消費者在網路訂購商品當日起，7 天內享有退換貨的保障\n⑤網購可買到較便宜的商品，是因網路商店的進貨成本低","options":["①②","①②④","②④⑤","①②③⑤"],"answer":"A","official":"③網路商店是一種虛擬商店，在通路方面可以與實體\n商店結合\n④消費者在收到訂購商品後，7 天內享有退換貨的保障\n⑤網購可買到較便宜的商品，非因網路商店的進貨成\n本低"},{"id":"112-3-A-13","exam":"112-3","q":13,"unit":"商業概論","topic":"商業概論","stem":"有關業種與業態的敘述，下列何者正確？\n①以商業的發展史來看，先有業種店，再發展業態店\n②業態店以直接販賣商品為出發點\n③業態店有較多樣的行銷活動\n④水果攤、包子店皆屬於業種店\n⑤業態店較能滿足消費者一次購足的需求","options":["①②③④","①②④⑤","①③④⑤","②③④⑤"],"answer":"C","official":"②業態店是「經營形態」來區分行業，為滿足顧客需\n求，以不同銷售方式來販賣多樣化商品"},{"id":"112-3-A-14","exam":"112-3","q":14,"unit":"商業概論","topic":"商業概論","stem":"連鎖企業組織型態有委託加盟連鎖、特許加盟連鎖、自願加盟連鎖及合作加盟連鎖，其中共有幾種型態\n是由加盟者擁有店面的所有權？","options":["4 種","3 種","2 種","1 種"],"answer":"B","official":"店面所有權屬於加盟者的有特許加盟、自願加盟、合\n作加盟"},{"id":"112-3-A-15","exam":"112-3","q":15,"unit":"商業概論","topic":"商業概論","stem":"某公司計劃推出自行研發的新產品在市場上銷售，該項產品經估算每月的總固定成本為$120,000，每單\n位的變動成本為$12，根據市場行情，每單位產品的售價為$42，則該公司每月應銷售多少單位，才會達\n到損益平衡？","options":["3000","4000","5000","6000"],"answer":"B","official":"損益平衡銷售量 () − ＝ 固定成本\n訂價 單位變動成本\n120000 4000\n(42 12) ＝ − ＝ 單位"},{"id":"112-3-A-16","exam":"112-3","q":16,"unit":"商業概論","topic":"商業概論","stem":"企業可透過異業結盟創造出 1 ＋ 1  2 的綜效，有關不同行業間的異業結盟特性，下列何者錯誤？","options":["結盟的雙方具有共同的合作目標","結盟雙方的合作方式是以訂定契約的方式來規範彼此的權利與義務","異業結盟可以增加新競爭者的進入障礙","雙方資源具有相似性以達到規模經濟效益"],"answer":"D","official":"(D) 結盟雙方的資源通常具有互補性","scan":"data:image/webp;base64,"},{"id":"112-3-A-17","exam":"112-3","q":17,"unit":"商業概論","topic":"商業概論","stem":"傳統商店因連鎖企業的發展迅速而逐漸式微，為了生存，傳統商店未來發展應有的對策不包括下列何者？","options":["可加強賣場規劃，提高吸引力","大量廣設分店，採取直營連鎖方式來提升規模經濟","接受政府的輔導","可與同性質商店結盟共同進貨來降低成本"],"answer":"B","official":"(B) 應該是投入連鎖加盟體系，享有較低廉的進貨成本"},{"id":"112-3-A-18","exam":"112-3","q":18,"unit":"商業概論","topic":"商業概論","stem":"漢斯(Hans)公司是英國一家食品公司，其銷售產品類型達 400 多種，近期受到經濟不景氣的影響，導致\n該公司的營業額日益下滑，因此漢斯公司決定針對不同類型的消費者，推出不同版本的商品型錄與促銷\n廣告策略以吸引消費大眾，希望激起消費者的購買慾望。由上述可知，漢斯(Hans)公司是採用何種促銷\n策略？","options":["奇數訂價策略","推式策略","路線策略","拉式策略"],"answer":"D","official":"拉式：針對消費者推出型錄及促銷策略"},{"id":"112-3-A-19","exam":"112-3","q":19,"unit":"商業概論","topic":"商業概論","stem":"小明是行銷公司總監，該公司來了一位新人，小明將此企劃案的整體決策告知新人，若今天新人是你，\n你該如何制訂行銷策略及目標市場選擇的決策，請將其正確之順序排列出來：\n①目標市場定位 ②選定目標市場 ③擬定行銷策略\n④分析各區隔市場 ⑤決定區隔變數 ⑥衡量各區隔市場之吸引力","options":["②→⑤→④→①→⑥→③","②→⑤→④→③→⑥→①","⑤→④→⑥→②→①→③","⑤→④→⑥→②→③→①"],"answer":"C","official":"⑤→④→⑥→②→①→③\n①目標市場定位：定位可帶來產品鮮明形象\n②選定目標市場：考量市場規模與成長潛力、競爭\n強度\n③擬定行銷策略：要如何將產品賣給消費者\n④分析各區隔市場：評估各市場區隔的吸引力與消費\n能力，並選定一個或多個區隔市場為經營重點\n⑤決定區隔變數：劃分市場所使用的標準\n⑥衡量各區隔市場之吸引力：區隔大小、未來成長競\n爭激烈與否，公司標標與資源多寡"},{"id":"112-3-A-20","exam":"112-3","q":20,"unit":"商業概論","topic":"商業概論","stem":"產品是企業經營活動的基本條件，也是交易過程中，企業用來滿足目標市場內消費者需求或慾望的財\n貨，有關產品的敘述，下列何者錯誤？","options":["產品可分為核心、基本、期望、附加及潛在等五個層次，其中核心產品指的是產品的功能或特性","好多多量販店提供購物後可全額退貨的服務，屬於附加產品","產品的包裝屬於有形產品，而售後服務屬產品政策中的引申產品","俗語說得好：「女為悅己者容」，因此年輕女孩子購買化粧品，並不是為了那動人的顏色，而是在購\n買一股對美麗容顏的憧憬和希望，此種產品層次是屬於核心產品"],"answer":"A","official":"(A) 核心產品是根本利益或效果，通常是抽象的概念"},{"id":"112-3-A-21","exam":"112-3","q":21,"unit":"商業概論","topic":"商業概論","stem":"假設廠商投資 80 萬元進行生產，生產每一單位成本為 16 元，該公司希望有 25%的投資報酬率，預期銷\n售量為 5 萬個。請問若以目標報酬訂價法，該產品應以多少訂價？","options":["10 元","20 元","30 元","40 元"],"answer":"B","official":"訂價 ＝ () × ＋\n目標投資報酬率 投資金額 單位成本 預估銷售量\n25% 800000 16\n50000\n() × ＝ ＋ ＝ 20 元"},{"id":"112-3-A-22","exam":"112-3","q":22,"unit":"商業概論","topic":"商業概論","stem":"某食品製造公司的行銷總監，希望能規劃對策，以因應產品生命週期四階段。如果你是這位經理，應該\n如何做？","options":["當產品在成熟階段時，必須採取提醒性廣告，盡可能維持市場地位","在產品仍處於成熟期，應該採取集中行銷策略，縮減營運或停止生產該產品","當產品進入成長期，應該採取告知性廣告，提高品牌知名度","當產品處於導入期，必須採取說服性廣告並擴大市占率"],"answer":"A","official":"(B) 為衰退期\n(C) 為導入期\n(D) 為成長期"},{"id":"112-3-A-23","exam":"112-3","q":23,"unit":"商業概論","topic":"商業概論","stem":"阿杰和小美在大學畢業後，一起創業開了咖啡店，雖然沒有另外聘請員工，但他們兩人合作無間，不論\n是內場餐點製作或是外場的服務，兩人都非常有默契的共同聯手完成；此外他們也與鄰近的書局及花藝\n店進行結盟，推出聯合促銷活動，以利提升店的銷售業績，由於店裡的生意越來越好，他們決定要向經\n濟部申請貸款，以作為爾後展店之用。有關阿杰與小美的創業敘述，下列何者正確？","options":["由於店內員工人數不滿 5 人，因此不符合我國經濟部對微型企業的定義","兩人申請貸款以籌措資金的方式，稱為眾籌","其符合組織規模小、相互支援性強、經營彈性大等特性","此屬於開設個人工作室的 SOHO 創業模式"],"answer":"C","official":"(A) 員工人數未滿 5 人，符合經濟部對微型企業的定義\n(B) 申請政府貸款方案，並不是眾籌\n(D) 屬於開設自營店的創業模式"},{"id":"112-3-A-24","exam":"112-3","q":24,"unit":"商業概論","topic":"商業概論","stem":"在 2020 年嚴重特殊傳染性肺炎(COVID-19)疫情管制期間，彼得依公司的防疫政策採行居家辦公，同時\n減少外出避免增加感染風險。彼得在家除上班之外，也利用網路購買了許多生活用品，準備讓自己好好\n在家當個「宅男」。彼得透過手機的 App 點餐，並且使用了電子支付方式付款，15 分鐘後，外送人員就\n將餐點送到彼得的家門口。彼得覺得今天的餐點好吃而且外送的速度很快，因此在 App 上給外送員及\n店家五顆星的最高評價。請問上述一共提及哪些現代化商業機能？","options":["商流、物流、金流、資訊流及服務流","商流、物流、金流、資訊流","物流、金流、服務流","商流、物流"],"answer":"A","official":"透過 App 點餐→資訊流。電子支付方式付款→金流。\n外送餐點到家→物流。App 上提供消費者使用後的評\n價→服務流。從點餐、付款到送餐後完成交易→商流"},{"id":"112-3-A-25","exam":"112-3","q":25,"unit":"商業概論","topic":"商業概論","stem":"近年來因咖啡受年輕人喜愛，帶動咖啡及週邊商品的銷售量，小美看到了這個商機，因此與同學合資開\n了一間複合式咖啡廳，店內所賣產品有咖啡飲品、咖啡豆、茶類相關飲品及甜點等四種，系列下的每樣\n產品皆有大/小 size 供消費者選擇，各類產品線的項目如下：\n咖啡飲品系列：美式咖啡、義式咖啡、拿鐵\n咖啡豆系列：臺灣咖啡豆、巴西咖啡豆、肯亞咖啡豆、衣索比亞咖啡豆\n茶類飲品系列：紅茶、綠茶、茶拿鐵\n甜點系列：蛋塔、牛角、可頌\n請問小美的咖啡廳產品組合的廣度、總長度及綠茶的深度各為多少？","options":["2、13、12","4、13、2","13、4、11","14、2、2"],"answer":"B","official":"廣度：所有「產品線」的數目，即廣度 ＝ 4\n長度 ＝所有產品線產品項目加總 ＝ 3 4 3 3 13 ＋ ＋＋＝\n每樣產品皆有大/小 size 深度 ＝ 2"}]);
Object.assign(window.CONTEXTS,{});
window.QUESTIONS.push(...[{"id":"112-4-A-1","exam":"112-4","q":1,"unit":"商業概論","topic":"商業概論","stem":"大雄、胖虎、小夫三人依法設立登記一家企業，名為「哆拉百貨」。胖虎以自己的「勞力價值」出資，\n小夫以 10 萬元現金出資並表明只願負擔 10 萬元的責任，三人言明由大雄當發起人並對哆拉百貨負無限\n責任。有關哆拉百貨的組織型態之敘述，下列何者錯誤？","options":["哆拉百貨的組織型態可能是合夥、有限合夥或兩合公司","哆拉百貨依法設立登記的「法」可能是「有限合夥法」也可能是「公司法」","胖虎的出資屬於無形資產，對企業必須負連帶無限責任","哆拉百貨具有法人資格，屬於社團法人"],"answer":"A","official":"(A) 依題意，哆拉百貨至少有一人(小夫)負有限責\n任，其餘兩人(胖虎、大雄)負連帶無限責任，因合夥\n皆是負連帶無限清償責任，故可判斷其不屬於合夥，\n而有可能屬於有限合夥企業或兩合公司"},{"id":"112-4-A-2","exam":"112-4","q":2,"unit":"商業概論","topic":"商業概論","stem":"「草莓趣味教學農場」的官網提到其營業項目，包括提供機關團體及民眾鮮採草莓、認識草莓品種導覽\n解說、草莓種植 DIY 教學等。以商業價值區分商業的發展而言，下列何者不包括在上述草莓趣味教學\n農場的營業項目之中？","options":["農業經濟","工業經濟","服務業經濟","體驗經濟"],"answer":"B","official":"農場直接利用草莓創造農業(種植草莓)、服務業(導覽\n及教學)及體驗(採果與 DIY)經濟，未涉及工業生產"},{"id":"112-4-A-3","exam":"112-4","q":3,"unit":"商業概論","topic":"商業概論","stem":"85 度 C 全球第 1000 家店在美國第四大城─德州休士頓開幕了。很難想像，85 度 C 最初只是新北市永\n和區的街邊小店，如今已是資本額高達 18 億的公開上市公司。隨著組織規模的擴大，85 度 C 總公司開\n始進行一連串改革，包括針對烘焙產品拆解每項產品的製作流程，拍照、錄影做成「教戰手冊」及員工\n訓練教學影片。另外，又斥資數億興建中央工廠，負責揉製麵糰、整型等半成品的後廠作業，讓門市人\n員只須負責發酵、烘烤、裝飾，即可將麵包、蛋糕上架，提高效率。根據上述，並未提到何種現代商業\n特質？","options":["分工專業化","資本大眾化","管理人性化","生產標準化"],"answer":"C","official":"(C) 文中未提及顧慮員工需求的管理人性化方式"},{"id":"112-4-A-4","exam":"112-4","q":4,"unit":"商業概論","topic":"商業概論","stem":"某建設公司因施工不當，造成 25 戶鄰宅傾毀，事發隔天股價開盤即跳空跌停。此建設公司於清晨發布\n重大訊息，承諾積極處理危機事件維持公司正常營運，絕不推卸相關責任，將會對受損戶盡到最大程度\n慰問、關懷與協助安置，至於相關損失金額、後續理賠則將依法處理。據調查，是建設公司在施工過程\n中，忽視異常數值最終釀禍，恐涉及違反建築技術規則，致生公共危險罪。根據上述內容，此建設公司\n善盡何種社會責任？\n甲、經濟責任 乙、法律責任 丙、倫理責任 丁、慈善責任","options":["甲乙丙","甲乙丁","乙丙丁","甲乙丙丁"],"answer":"A","official":"①該公司積極處理危機事件維持公司正常營運，善盡\n經濟責任\n②依法賠償受災戶，善盡法律責任\n③對受損戶給予關懷安置，善盡倫理責任"},{"id":"112-4-A-5","exam":"112-4","q":5,"unit":"商業概論","topic":"商業概論","stem":"和花、和葉、圓潤、二狗四個人是好朋友，他們大學畢業後都成了 SOHO 族。和花白天上班，晚上在\n家當 YouTuber 從事熊貓影片剪輯創作；和葉自己成立個人工作室，接案從事手機 APP 開發和系統維護；\n圓潤取得記帳士執照後，在家開業聘請 3 位助理，從事工商服務；二狗從事保險經紀人工作，除了每週\n一次回公司開會之外，其餘時間在家上班。若以工作性質和工作自主程度區分四人的 SOHO 類型，下\n列何者正確？","options":["和花：創意型及兼職型","和葉：資訊型及兼職型","圓潤：諮商型及自雇型","二狗：業務型及兼職型"],"answer":"A","official":"(B) 和葉：資訊型及自雇型\n(C) 圓潤：諮商型及創業型\n(D) 二狗：業務型及在職型"},{"id":"112-4-A-6","exam":"112-4","q":6,"unit":"商業概論","topic":"商業概論","stem":"下列哪些網路開業方式的主要收入是銷貨收入？\n①設立網路商店 ②經營入口網站 ③從事網路拍賣賣家\n④擔任 Podcast 創作者 ⑤經營線上遊戲供玩家遊玩 ⑥經營 IG 社群分享美食地圖","options":["①②③","①③⑤","②④⑤","③⑤⑥"],"answer":"B","official":"②廣告費收入\n④⑥業配費收入\n⑤線上遊戲業者銷售遊戲點數、虛擬寶物等屬於銷貨\n收入","scan":"data:image/webp;base64,"},{"id":"112-4-A-7","exam":"112-4","q":7,"unit":"商業概論","topic":"商業概論","stem":"新冠肺炎疫情持續長達 2 年以上，受到各國政府防疫措施的限制及民眾自主防疫避免群聚等因素，使得\n臺灣的餐飲、航空、旅遊和百貨零售等行業業績大受影響，有些企業長期入不敷出、周轉困難被迫關門\n歇業。不過，疫情也意外帶動所謂「宅經濟」的蓬勃發展，送餐業和電商交易逆勢上揚。以外送餐點為\n例，除了原本的小吃餐飲之外，許多知名星級飯店也紛紛改弦易轍加入外送的行列，一時間百家爭鳴競\n爭激烈。對企業而言，經營過程充滿各種風險，下列敘述何者錯誤？","options":["新冠疫情屬於災害風險","入不敷出周轉困難屬於資金風險","政府防疫政策限制屬於經營風險","新競爭者加入屬於市場風險"],"answer":"C","official":"(C) 政府政策限制屬於法律風險"},{"id":"112-4-A-8","exam":"112-4","q":8,"unit":"商業概論","topic":"商業概論","stem":"有關經濟部商業司所提出的商業現代化措施與計畫，下列敘述何者正確？","options":["全面檢討修正公司法有助於提升商業技術水準","規範定型化契約有助於強化財團法人的經濟功能","推動的優良服務認證計畫簡稱 CSI，有助提升維護商業秩序","設置工商綜合區有助於促進城鄉均衡發展"],"answer":"D","official":"(A) 全面檢討修正公司法有助於健全營運主體\n(B) 規範定型化契約有助於保護消費者權益\n(C) 優良服務認證計畫簡稱 GSP，有助於提升商業服\n務品質"},{"id":"112-4-A-9","exam":"112-4","q":9,"unit":"商業概論","topic":"商業概論","stem":"消保法明訂消費者對於通訊交易、訪問交易所購買的商品或服務應有七天猶豫期，可在收到商品後七天\n內「無條件」退貨。下列商品何者適用於上述規定？","options":["在易遊網訂購的東京 5 日遊來回機票","付費的天下雜誌電子期刊","線上購買的鮮奶","未拆封的網購內衣褲"],"answer":"D","official":"(A)(B)(C)三個選項各自有不用理由不適用七天猶豫\n期之規定：\n(A) 航空機票開立即進入服務流程，無法無條件退貨\n(B) 付費的天下雜誌電子期刊一提供便完成交付使用\n(C) 鮮奶保存期限較短且易腐敗"},{"id":"112-4-A-10","exam":"112-4","q":10,"unit":"商業概論","topic":"商業概論","stem":"有關商流的敘述，下列何者錯誤？","options":["商流包括廠商的進貨、銷貨及存貨作業，是所有流通活動的源頭","商流最主要且最重要的功能是發掘消費者需求","電腦、家電類的商品應採用選擇型商流，提供專業服務","產品價格低、購買頻率高的日常用品適用於開放型商流"],"answer":"B","official":"(B) 商流最主要的功能是執行所有權的移轉"},{"id":"112-4-A-11","exam":"112-4","q":11,"unit":"商業概論","topic":"商業概論","stem":"有關「零售業」的敘述，下列何者錯誤？","options":["零售業是商業體系中最能反映社會結構轉型和消費者需求變化的行業","零售業可以促進產銷專業分工","中華民國行業統計分類將零售業區分成有店舖零售業及無店舖零售業","家樂福、好市多等量販店結合倉儲與賣場，兼具批發與零售特性，屬於滿足顧客一次購足的零售業態"],"answer":"C","official":"(C) 中華民國行業統計分類將零售業區分成綜合商品\n零售業、專賣零售業"},{"id":"112-4-A-12","exam":"112-4","q":12,"unit":"商業概論","topic":"商業概論","stem":"有關「無店舖零售業」的敘述，下列何者正確？","options":["多層次傳銷屬於直效行銷的一種類型","廠商在世貿中心電腦展上設置專屬櫃位販售電腦及其周邊商品，屬於有店舖零售","行銷大師科特勒將無店舖零售業分為直銷、直效行銷和人員銷售三類","所謂直效行銷就是消費者保護法中所稱的「通訊交易」"],"answer":"D","official":"(A) 多層次傳銷屬於人員銷售的一種\n(B) 會展屬於無店舖零售\n(C) 分成自動販賣、人員銷售、直效行銷"},{"id":"112-4-A-13","exam":"112-4","q":13,"unit":"商業概論","topic":"商業概論","stem":"聯強國際集團本身是一間向 3C 製造商購進商品後再賣給下游零售商的跨國公司，隨著運籌功能在產業\n鏈中的角色日趨重要，於 2016 年成立「通達智能運籌公司」，同時啟用占地 4,700 坪的物流中心，整合\n自家產品到宅、雲倉、配送、技術及維修等五大服務。為共享倉儲及物流資源，該物流中心亦兼營配送\n供應鏈廠商之貨物。根據上述，若依成立者與經營型態區分，聯強國際集團旗下的「通達智能運籌」物\n流中心屬於下列何者？","options":["批發商型／營業型物流中心","製造商型／專用型物流中心","零售商型／中立型物流中心","轉運型／封閉型物流中心"],"answer":"A","official":"由題目敘述可知，聯強國際向 3C 製造商購入商品再\n賣給下游零售商，屬於批發商；其所成立的「通達智\n能運籌」物流中心屬於批發商型物流中心。另外，此\n物流中心除了為集團運送商品外，也替供應鏈廠商運\n送商品，故為營業型物流中心","scan":"data:image/webp;base64,"},{"id":"112-4-A-14","exam":"112-4","q":14,"unit":"商業概論","topic":"商業概論","stem":"全聯福利中心(PX Mart)，是本土的連鎖超級市場，成立於 1998 年 10 月，目前據點數量居於各超市品牌\n之冠。全聯各連鎖店均由集團總部百分之百出資，店面所有權與管理權皆歸總部。有關這種連鎖組織的\n敘述，下列何者錯誤？","options":["全聯屬於直營連鎖體系(Regular Chain)","店長可獲得百分之百的利潤分配","管理權集中，較易貫徹公司政策","公司總部必須負擔展店所有費用，資金壓力較大，拓店速度較慢"],"answer":"B","official":"(B) 直營連鎖店長為總部所聘任之員工，領取公司薪\n資而非百分之百利潤分配"},{"id":"112-4-A-15","exam":"112-4","q":15,"unit":"商業概論","topic":"商業概論","stem":"cama café 咖啡官網的招募加盟區標題為「讓專業永續事業─讓生活與工作是自己喜歡的樣子」，強調加\n盟 cama café 咖啡：「實賺實拿 0 抽成─利潤 100%為加盟者所有」、「與 cama café 加盟合約期為 3 年 3\n個月；接下來兩年一次續約、不會收取額外費用」、「總部有提供完整的經營輔導及進貨模式，加盟主可\n彈性自由選擇」。根據上述加盟說明，可以判斷 cama café 比較偏向下列何種連鎖組織？","options":["委託加盟","特許加盟","自願加盟","合作加盟"],"answer":"C","official":"加盟者享有 100%利潤分配，加盟者對進貨有一定的\n自由度，總部有提供經營技術指導，比較偏向自願加\n盟型態"},{"id":"112-4-A-16","exam":"112-4","q":16,"unit":"商業概論","topic":"商業概論","stem":"根據國泰金控最新消息指出：國泰金控與蝦皮購物合作，為協助蝦皮賣家轉型成電商，若有資金需求時，\n即可使用國泰金控「蝦米貸」方案服務。該服務內容是指在賣家同意下，蝦皮將其商戶資訊及營運狀況\n等數據自動帶入國泰金控獨有的信用評分模型，試算後即可提供賣家相對應的可貸資金額度以供參考。\n由上述可判斷國泰金控與蝦皮購物的異業合作型態是屬於下列何種？","options":["技術研究發展型結盟","財務型結盟","人力資源型結盟","資訊型結盟"],"answer":"D","official":"國泰金控與蝦皮購物在客戶同意的前提下，透過客戶\n情報交流的機制達到雙方各自的業務目的，此乃資訊\n型異業結盟"},{"id":"112-4-A-17","exam":"112-4","q":17,"unit":"商業概論","topic":"商業概論","stem":"有關某公司新產品「超輕薄縮腹馬甲」的有效市場區隔條件分析敘述，下列何者錯誤？","options":["根據統計，臺灣 20 歲以上的女性人口有 800 萬，其中 80%有小腹突出的困擾：可衡量性","美體塑身的市場商機每年高達千億，相關商品有利可圖，本公司可以努力開發這個市場：足量性","消費者在電視、網路媒體以及百貨公司、服飾店、賣場等通路都有機會接觸到本公司商品的訊息或\n實體商品：可接近性","因為資金及人力限制，本產品暫時不考慮開展海外市場：足量性"],"answer":"D","official":"(D) 屬於可行動性的問題"},{"id":"112-4-A-18","exam":"112-4","q":18,"unit":"商業概論","topic":"商業概論","stem":"下列何者屬於產品生命週期中「成長期」的行銷目標或市場特色？\n①維持顧客對產品的忠誠度 ②建立消費者的品牌偏好 ③提高產品知名度\n④擴大產品市場占有率 ⑤銷售量達到最高點 ⑥利潤達到最高點","options":["①③⑤","①④⑥","②④⑥","③④⑤"],"answer":"C","official":"維持顧客對產品的忠誠度：成熟期\n③提高產品知名度：導入期\n⑤銷售量達到最高點：成熟期"},{"id":"112-4-A-19","exam":"112-4","q":19,"unit":"商業概論","topic":"商業概論","stem":"香香美髮公司共推出銀髮、青壯、熟女、少男、少女、兒童、嬰兒等 7 條洗髮精產品線，各條產品線的\n產品項目分別有 2 種、4 種、5 種、4 種、4 種、2 種、2 種；其中，熟女薰衣草洗髮精有 1000 ml、500 ml、\n250 ml 等 3 種規格；銀髮何首烏洗髮精有瓶裝、管裝等 2 種規格。根據上述，下列何者正確？","options":["香香美髮公司的產品組合廣度為 23","香香美髮公司的產品組合長度為 7","熟女薰衣草洗髮精的產品線深度為 3","銀髮何首烏洗髮精的產品線長度為 2"],"answer":"C","official":"(A)(B) 產品線廣度為 7、長度為 23\n(D) 銀髮何首烏洗髮精的產品線深度為 2"},{"id":"112-4-A-20","exam":"112-4","q":20,"unit":"商業概論","topic":"商業概論","stem":"烏龍派出所大原所長對所裡同仁的工作設計做了一些調整如下，請判斷下列選項何者符合正確的工作設\n計原則？\n①賦予寺井更大的權責，請他負責協調所有同仁的輪值排班\n②麗子原先專門負責婦女案件，請她再多負責處理兒童相關案件\n③兩津原先負責案件書面資料整理與歸檔，大原所長重新設計檔案歸檔的 SOP、寫成作業手冊，讓兩\n津的工作有所依據\n④中川專責保安科已經三年了，大原所長有意栽培他往警察總署邁進，於是將他調任至外事科、訓練科、\n行政科部門歷練","options":["寺井：工作豐富化／兩津：工作簡單化","麗子：工作豐富化／中川：工作輪調","兩津：工作豐富化／麗子：工作擴大化","中川：工作擴大化／寺井：工作輪調"],"answer":"A","official":"①寺井權責增加：工作豐富化\n②麗子平行工作項目增加：工作擴大化\n③兩津有工作手冊可依循：工作簡單化\n④中川調部門歷練：工作輪調"},{"id":"112-4-A-21","exam":"112-4","q":21,"unit":"商業概論","topic":"商業概論","stem":"美美是人資部專員，最近公司打算招聘一批公關人員，人資經理指派美美要設計 2 項筆試測驗，目標要\n能有效衡量應徵者①個人的價值觀、興趣及個性等特質，以及②個人未來職業發展的潛在能力。請問美\n美應該採取哪兩種測驗類別？","options":["性向測驗、成就測驗","人格測驗、智力測驗","成就測驗、智力測驗","人格測驗、性向測驗"],"answer":"D","official":"個人的價值觀、興趣及個性：人格測驗\n②個人未來職業發展的潛在能力：性向測驗"},{"id":"112-4-A-22","exam":"112-4","q":22,"unit":"商業概論","topic":"商業概論","stem":"有關工作分析的敘述，下列何者正確？","options":["工作分析是工作評價的延伸","目前最普遍被採用的工作分析法為綜合法","工作分析後用來說明工作人員所需條件的書面文件稱為工作規範","工作分析人員直接詢問員工之工作內容並加以記錄的方式屬於工作日誌法"],"answer":"C","official":"(A) 工作評價是工作分析的延伸\n(B) 目前最普遍被採用的工作分析法為問卷調查法\n(D) 工作分析人員直接詢問員工之工作內容並加以記\n錄的方式屬於面談法"},{"id":"112-4-A-23","exam":"112-4","q":23,"unit":"商業概論","topic":"商業概論","stem":"甲公司今年的銷貨淨額為$1,000,000，期初存貨為$120,000、期末存貨為$180,000。根據上述資料，判斷\n下列何者錯誤？","options":["若甲公司的毛利率要維持在 25%以上，則其銷貨成本應控制在$750,000 以下","若甲公司的成本率為 60%，則其存貨周轉率為 2 次","若甲公司的銷貨成本為$450,000，則其存貨每 4 個月會周轉一次","若甲公司的毛利率為 40%，同業的存貨周轉率平均為 3，則表示甲公司對存貨的控制能力相對較佳"],"answer":"B","official":"(A) 銷貨成本率要控利在 75%以下，故銷貨成本\n＝ 1,000,000× 75% ＝ 750,000 以下\n(B) 存貨周轉率 1,000,000 0.6 4\n150,\n()\n000\n× ＝ ＝\n(C) 存貨周轉率 3 50,000\n10\n4\n50, 00 ＝ ＝\n存貨周轉月數 12 4\n3 ＝ ＝ 個月\n(D) 存貨周轉率 1,000,000 (1 40% 4\n150,000\n×− ) ＝ ＝ ，甲公司的\n存貨周轉率是 4，高於同業的 3，存貨周轉率越高，\n銷售能力及控制能力愈佳，故甲公司對存貨的控制能\n力相對較佳"},{"id":"112-4-A-24","exam":"112-4","q":24,"unit":"商業概論","topic":"商業概論","stem":"光子經營健康蔬食館多年，目前拓展新據點，因此向銀行申請貸款。銀行根據 5C 信用品質衡量指標來\n判斷該給光子多少貸款額度。銀行根據調查後，列出光子所符合的條件如下：\n①健康蔬食風氣在臺灣正在盛行，市場規模逐年有 15%以上的成長率\n②光子的健康蔬食館營業額逐年成長，淨利率優於同業，商店具備還款能力且償債紀錄佳\n③光子履行償債義務的可能性大，承諾付款的可信度良好，不論是信用卡或貸款皆無延遲還款\n④光子的健康蔬食館歷年的流動比率平均在 200%以上、負債比率平均在 45%以下，財務狀況優於同業\n請問光子「依序」具備哪些 5C 條件？","options":["經濟情況／能力／品德／資本","擔保／經濟情況／能力／資本","能力／擔保／資本／經濟情況","經濟情況／資本／品德／能力"],"answer":"A","official":"市場規模逐年成長：經濟情況\n②淨利率優於同業，商店具備還款能力：能力\n③信用良好，無延遲還款：品德\n④財務報表優於同業：資本"},{"id":"112-4-A-25","exam":"112-4","q":25,"unit":"商業概論","topic":"商業概論","stem":"甲公司有臨時性的資金需求，財務部門需要籌措短期資金，請問下列哪些融資方式是甲公司可以考慮採\n用的？\n①發行股票 ②押匯 ③票據貼現 ④分期付款融資 ⑤發行商業本票 ⑥租賃融資","options":["①②③","②③⑤","②④⑥","③⑤⑥"],"answer":"B","official":"①為長期資金籌措方式\n④⑥為中期資金的籌措方式"}]);
Object.assign(window.CONTEXTS,{"112-5-21-25":{"text":"韓國某電商集團於後疫情時代拓展跨國市場，初步進軍日本與臺灣市場。然而，受到日本人口結構與\n成熟的超商網路影響，該集團於 2023 年決定退出日本市場，將海外重心轉向臺灣。\n其在韓國大邱的智慧倉儲物流中心為自建，運用 AI 控制的機器人進行撿貨與分類，以降低員工業務量；\n其能持續投入物流建設其中一個重要原因，是來自日本軟銀集團挹注的願景基金。在臺灣，該集團一開始\n先租用長榮的倉儲，請黑貓宅急便負責配送。為因應當前電商資安外洩頻傳的問題，該集團更與工研院合\n作，交流物流隱碼技術規格，以最大程度保護消費者個資。不論在韓國或臺灣，該集團皆主打速配 24 小時\n快速到貨服務；臺灣跨境運送一星期到貨，且提供消費滿額免運和首購優惠，更能快速吸引消費者下單。\n該集團現已陸續推出供消費者使用信用卡、行動支付及貨到付款等多元支付方案。\n此外，該集團商品除了向供應商採購並大量買斷外，也委請上游製造商生產，並冠上電商本身的品牌\n(CPLB)進行銷售，出口到許多亞洲國家、澳洲與美國等地。"}});
window.QUESTIONS.push(...[{"id":"112-5-A-1","exam":"112-5","q":1,"unit":"商業概論","topic":"商業概論","stem":"某文教集團除了出版教科書之外，同時也致力於私立學校的經營。其以「雙語教育為基礎，發展國際接\n軌課程，進行全人教育」的理念來打造中小學教育。事業版圖跨足臺灣、中國與泰國，更與泰國教育專\n家合作，共同編製幼兒教材。隨著事業體的茁壯，董事長也重視員工的健康，在總部設置游泳池、健身\n房、球場等，鼓勵同仁積極運動，在產銷活動方面，引進環保與綠色生產概念，實施去光碟化與回收舊\n書，為環境永續盡一份力量。依據上述資訊，下列何者正確？","options":["「雙語教育為基礎，發展國際接軌課程，進行全人教育」為集團正在針對所創辦的中小學教育進行\n目標行銷中的分析市場環境","董事長在總部設置的「游泳池、健身房、球場」，屬於教育性福利","集團版圖符合經營國際化特質，並與泰國專家提供消費者體驗經濟時期的產品","該集團處於社會責任觀念發展中的廠商責任時期"],"answer":"D","official":"(A)「雙語教育為基礎，發展國際接軌課程，進行全\n人教育」屬於目標行銷中的市場定位\n(B) 董事長在總部設置的「游泳池、健身房、球場」，\n屬於娛樂性福利\n(C) 體驗經濟時期是指企業提供消費者情境式體驗以\n及感受化的產品，文中敘述無法看出集團此一特質"},{"id":"112-5-A-2","exam":"112-5","q":2,"unit":"商業概論","topic":"商業概論","stem":"2023 年經濟部商業司推出智慧減碳補助計畫，協助中小企業實現數位轉型，如智慧點餐、智慧物流、\n智慧優化送貨路線等方面的智慧營運，期能提升企業的經營效率，同時實現節能減碳並降低成本。商家\n只要符合標準認列範圍，即能申請補助。試問上述屬於商業現代化的何種發展策略？","options":["落實消費者權益之保護","強化商業團體及財團法人經濟功能","提升商業技術水準","擴大營運空間、改善商業環境"],"answer":"C","official":"(C) 智慧減碳補助計畫鼓勵企業運用現代化技術加強\n經營管理與營運效率，屬於商業現代化中的提升商業\n技術水準"},{"id":"112-5-A-3","exam":"112-5","q":3,"unit":"商業概論","topic":"商業概論","stem":"某幼稚園園長為大班小孩辦理畢業餐會，特地在知名麵包店的官方網站訂購其自製的低糖卡通鮮奶油海\n綿蛋糕。園長貼心地提出要求將同學名字與祝福的話寫在蛋糕上，並請店家在餐會前一日宅配。送達當\n天，園長拆封檢視時發現，店家將多位同學名字張冠李戴，只好趕緊到附近蛋糕店採買補救。餐會當日\n園長發現外包場地服務人員手忙腳亂，亦未能及時為來賓收拾桌上使用過的餐盤。依據上述情況，下列\n何者正確？","options":["由於服務具不可分割性，外包場地服務人員所產生的問題，企業應定期舉辦教育訓練提升服務品質","此網站依電子商務經營模式區分，屬於 C to B","特種交易依據消費者保護法皆適用七天猶豫期的無因退貨處理","依通路階層區分，園長於麵包店的官方網站下單而產生的商流屬於一階通路"],"answer":"A","official":"(B) 此網站依電子商務經營模式區分，屬於 B to C\n(C) 依據消費者保護法，特種交易中的通訊交易與訪\n問交易買方具七天猶豫期，但不包括不受七天猶豫期\n限制的產品，其中有易腐敗且客製化商品無法與商家\n進行退換貨等處理，但因為是收到貨後發現有瑕疵，\n仍可另外與業者進行退換貨等適當主張\n(D) 園長於麵包店的官方網站下單而產生的商流屬於\n零階通路"},{"id":"112-5-A-4","exam":"112-5","q":4,"unit":"商業概論","topic":"商業概論","stem":"某連鎖便利商店和某珠寶品牌攜手合作，共同推出母親節預購活動，主打消費者所選的每一顆鑽石都對\n環境友善，獲得國際碳中和認證。此外，會由專業客服進行個別調整與戒圍量測，致力於打造屬於顧客\n獨特美好而純淨的愛。預購期間，只要憑該便利商店電子票證(例如預付卡)結帳即享有折扣優惠；消費\n者也能透過掃描型錄上的 QR code 了解更多活動資訊。依據上述，下列何者錯誤？","options":["從行銷管理觀念的演進分析，該珠寶企業屬於社會行銷導向","「結帳即享有折扣」是屬於訂價策略中的滲透訂價法","上述異業合作屬於行銷與售後服務結盟","文中提到「由專業客服進行個別調整與戒圍量測」是屬於現代商業特質中的商品客製化"],"answer":"B","official":"(B)「結帳即享有折扣」屬於短期誘因的促銷手段；\n滲透訂價法則屬於產品新上市為擴大市佔率的一種\n訂價方式"},{"id":"112-5-A-5","exam":"112-5","q":5,"unit":"商業概論","topic":"商業概論","stem":"小梅暑假到日本旅遊，除了欣賞當地景點外，便是到 AEON 購物中心與大國藥妝店採購。除了實體購\n物之外，她還在日本亞馬遜網站上購入吸塵器與吹風機，選擇宅配到入住的飯店，使行程更輕鬆享受。\n回國前，她習慣將身上全部的日幣在機場的自動販賣機花光。依據上述，下列哪些正確？\n①自動販賣機屬於無店鋪零售業中的直效行銷\n②一般而言，進入 AEON 可以看到大型停車場，且 AEON 不僅提供購物，還有休閒、餐飲與娛樂等功\n能，屬於具有主力商店且能讓消費者一次購足的商業空間\n③大國藥妝店屬於專賣店，商品款式豐富多樣，且顧客提袋率高，符合全客層需求\n④在亞馬遜網路上所購入的商品，屬於網路購物中的實體商品","options":["②③","②④","①②④","①③④"],"answer":"B","official":"①自動販賣機屬於無店鋪零售業，但非直效行銷\n③大國藥妝店屬於專賣店，商品款式豐富多樣，且顧\n客提袋率高，能滿足特定需求的顧客"},{"id":"112-5-A-6","exam":"112-5","q":6,"unit":"商業概論","topic":"商業概論","stem":"大學畢業的琪琪正在考慮自己開服飾店將商品販售給最終消費者還是做成衣批發，以下是琪琪針對上述\n兩者的比較，下列敘述何者錯誤？","options":["零售商較重視行銷，多以人員拜訪提高商品銷售量","零售商通常會將店面開設於交通便利的地點，其服務對象為最終消費者","批發商通常不需重視店內裝潢與廣告","批發商通常需投入較大資本，會與顧客建立長期合作關係"],"answer":"A","official":"(A) 零售商多以廣告促銷活動提高商品銷售量；多以\n人員拜訪提高商品銷售量的是「批發商」"},{"id":"112-5-A-7","exam":"112-5","q":7,"unit":"商業概論","topic":"商業概論","stem":"某家市場麵攤自第二代接班人接手後開起直營連鎖麵館，為了推廣自家美食，更建立網路商店與經營\nYouTube 頻道。在頻道中店家提及：「為了建立連鎖分店，決定統一規劃各項作業流程，為每一道菜建\n立固定工序。由於本身專注研發湯頭，麵條則委請其他專業工廠協助生產，運用專業分工提升經營效率。」\n依據上述，下列何者錯誤？","options":["此麵館由於建立連鎖分店，所以對於資金的負擔較高，但對分店的控制力高，較能維持企業形象","此麵館運用策略性外包的方式將非核心技術交由其他廠商負責","從未來商業發展趨勢分析，此麵館具備多角化經營的特質","「為了建立連鎖分店，決定統一規劃各項作業流程，為每一道菜建立固定工序」具備連鎖企業 3S 管\n理原則中的標準化原則"],"answer":"C","official":"(C) 從未來商業發展趨勢分析，此麵館因同時開立實\n體麵館、網路商店及經營 YouTube 頻道，表示其具備\n業態多樣化的特質；經營多角化多指跨產業經營以分\n散風險，題幹並無此敘述"},{"id":"112-5-A-8","exam":"112-5","q":8,"unit":"商業概論","topic":"商業概論","stem":"48 歲中年失業的老翟想和 3 位夥伴一起創業開一家文青咖啡店。請問下列敘述何者錯誤？","options":["在創業評估階段，應先擬定創業計畫書，檢視自己是否擁有創業可能性","老翟可向勞動部申請微型創業鳳凰貸款","其創業方式以自主程度區分，屬於創業型 SOHO 族","該咖啡店若開始營運後，由於員工數較少，彼此可相互支援、工作互補性大"],"answer":"A","official":"(A) 創業計畫書應在決定創業的創業準備階段擬定"},{"id":"112-5-A-9","exam":"112-5","q":9,"unit":"商業概論","topic":"商業概論","stem":"有關勞資制度，下列敘述何者符合勞工相關法令規範？","options":["補習班雇用 15 歲以上的童工週一到週五早上 9 點到 12 點打電話協助招生","2015 年 7 月 1 日後的到職員工，自己須提撥每個月工資的 6%以上做為退休金提撥","大學生宗介在 2024 年兒童節到樂園打工，雇主約定時薪為 180 元","工地主任扣留工人薪資，說明等房子蓋好、業主驗收通過才核發，目前薪資為工程保留款"],"answer":"A","official":"(A) 根據勞基法，企業可以任用童工(15 歲以上未滿\n16 歲之人)，但須符合對於工作性質與工作限制的相\n關規範\n(B) 2015 年 7 月 1 日後的到職員工，雇主應提撥員工\n每個月工資的 6%以上做為退休金提撥；勞工可按月\n自願提繳每月工資最多 6%的退休金\n(C) 大學生宗介在 2024 年兒童節到樂園打工，時薪最\n低必須給予 2024 年基本工資 183 元\n(D) 企業不得預扣勞工工資作為違約金或賠償費用"},{"id":"112-5-A-10","exam":"112-5","q":10,"unit":"商業概論","topic":"商業概論","stem":"一家新創公司於臺北花博就業博覽會上積極招募遊戲程式設計師，這份工作涵蓋 PC 線上遊戲功能的開\n發與日常維護，並需要和企劃與美術團隊密切合作與相關功能的開發，以支持營運活動。有意應徵者除\n了參與面談外，公司會進行相關測驗來瞭解應試者未來的職業發展潛能。依據上述，下列何者正確？","options":["該公司徵才方式的優點是較能熟悉企業文化，並降低訓練成本","此工作適合採用工作分析法中「觀察法」分析","此工作負責內容應歸類在「工作規範」的書面紀錄中","上述測試職業發展潛能的測驗應為性向測驗"],"answer":"D","official":"(A) 此為外部徵才方式，無法馬上熟悉企業文化，訓\n練成本較高\n(B) 觀察法適用於較高勞動性、固定且重複的工作，\n不適合用來分析遊戲程式設計師\n(C) 此工作負責內容應歸類在「工作說明書」的書面\n紀錄中"},{"id":"112-5-A-11","exam":"112-5","q":11,"unit":"商業概論","topic":"商業概論","stem":"有關財務管理相關概念的敘述，下列何者正確？","options":["某科技代工廠因零組件成本價跌，大批買進，此為持有現金的預防動機","某半導體業看準先進封裝產能供不應求而調整營運方向，屬於財務規劃中的市場因素","某跨國集團為降低負債比，可發行公司債募集資金","某批發商將信用期間拉長，以便讓客戶能儘早償付款項"],"answer":"B","official":"(A) 某科技代工廠因零組件成本價跌，大批買進，此\n為持有現金的「投機」動機\n(C) 發行公司債將提高企業負債比\n(D) 某批發商可提供現金折扣，以便讓客戶能儘早償\n付款項；若將信用期間拉長，可能導致呆帳產生"},{"id":"112-5-A-12","exam":"112-5","q":12,"unit":"商業概論","topic":"商業概論","stem":"某電信業者受到電信業之間合併案風波的影響，引發外界對同屬集團內的關係企業(包括電商、遊戲等\n多元業務)的質疑。公司必須審慎評估在合併後是否將獲得電信市場中的「客戶名單、數據統計」等資\n訊，因而協助集團子企業取得市場競爭的高度優勢，引發不公平競爭的爭議。然而公司總經理指出，合\n併後不僅有助電信產業發展，還能改善原用戶的網路覆蓋，更會保障被合併的原電信員工工作權。除此\n之外，總經理也提到企業本身持續實踐綠電能源的理念，致力於強化綠電的採購與使用率。依據上述，\n下列何者錯誤？","options":["企業綠電能源內容符合近年環境追求永續發展的趨勢","上述遭質疑的合併後獲得「客戶名單、數據統計」等資訊可能違反個資法","上述總經理認為合併後對員工的保障屬於企業社會責任中的經濟責任","此一電信業間的合併案屬於垂直整合"],"answer":"D","official":"(D) 此一電信業間的合併案屬於水平整合"},{"id":"112-5-A-13","exam":"112-5","q":13,"unit":"商業概論","topic":"商業概論","stem":"AI 概念股風起雲湧，以獲利能力而言，若投資人想要單從財務數字分析，下列哪一檔 AI 伺服器企業可\n能隱含較高的投資風險，但卻能同時代表投資人對公司未來成長性的較高期待？\nQ2 財務數字 AI 伺服器企業\nA 企業 B 企業 C 企業\n流動比 0.8 1 1.5\n毛利率 0.89 1.75 0.33\n總資產週轉率 0.85 0.76 0.79\n每股盈餘 12 3 7.5\n每股市價 144 105 97.5","options":["A 企業","B 企業","C 企業","沒有風險"],"answer":"B","official":"投資人可以運用本益比(每股市價 ÷ 每股盈餘)分析企\n業的投資風險並了解投資人對公司未來成長性的期\n待程度\nA 企業本益比 144 12\n12 ＝ ＝\nB 企業本益比 105 35\n3 ＝ ＝\nC 企業本益比 97.5 13\n7.5 ＝ ＝\nB 企業本益比高於同業 A、C，表示其隱含較高的投\n資風險與投資人對公司未來成長性的高度期待"},{"id":"112-5-A-14","exam":"112-5","q":14,"unit":"商業概論","topic":"商業概論","stem":"有關商業法律相關規定，下列何者正確？","options":["某上市公司不當使用競爭對手的產品名稱作為廣告關鍵字，易誤導消費者以為兩者有關聯，以提高\n網站流量和交易機會，然此種做法是榨取他人努力成果的不法行為，已違反「商品標示法」","根據「商標法」規定，商品之「原產地」、「主要成分或材料」、「淨重、容量、數量或度量等」、「製\n造年月或年週」及經濟部公告之其他應標示事項，得以國際通用文字或符號標示","某製筆工廠替一款具圓滑曲線體態、弧形嘴巴、多層次眼睛、圓形堆疊尾巴的毛毛蟲造型彩虹筆申\n請設計專利，期限從申請日開始起算 15 年屆滿","「食品安全衛生管理法」的立法本意為保障國民健康，防止職業災害產生"],"answer":"C","official":"(A) 某上市公司不當使用競爭對手的產品名稱作為廣\n告關鍵字，此種做法是榨取他人努力成果的不公平行\n為，已違反「公平交易法」\n(B) 根據「商品標示法」規定，商品之「原產地」、「主\n要成分或材料」、「淨重、容量、數量或度量等」、「製\n造年月或年週」及經濟部公告之其他應標示事項，得\n以國際通用文字或符號標示\n(D)「職業安全衛生法」立法目的之一為防止職業災\n害產生"},{"id":"112-5-A-15","exam":"112-5","q":15,"unit":"商業概論","topic":"商業概論","stem":"某微型企業主管運用工作設計讓員工更熟悉不同作業環境，並培養多功能人才。但評估過程中採用文字\n敘述語意不明，考核過了半年，員工才得知是否有薪資調整加薪或解雇的消息。依據上述，下列何者正\n確？","options":["上述工作設計原則屬於「工作豐富化」","上述企業可運用分等法進行績效評估","主管評估過程中出現「寬嚴問題」","企業進行獎懲失去「目的性」原則"],"answer":"B","official":"(A) 上述工作設計原則屬於「工作輪調」\n(B) 微型企業因人員較少，可採用分等法進行績效評估\n(C) 主管評估過程中出現「標準不明確」\n(D) 企業進行獎懲失去「時效性」原則"},{"id":"112-5-A-16","exam":"112-5","q":16,"unit":"商業概論","topic":"商業概論","stem":"根據下列敘述，哪些商家採用「心理變數」項目進行市場區隔？\n①某茶行推銷可以減少醣類吸收、降低內臟脂肪並減輕宿便負擔的苦瓜茶\n②某旅行社提供越野車愛好者四天三夜荒島開墾之旅\n③某麵店提供成人版與兒童版拉麵套餐\n④某咖啡連鎖店針對努力工作、積極享受生活的中產階級提供手沖哥倫比亞莊園咖啡\n⑤某精品店針對 VIP 忠實粉絲推出限量款生活周邊商品\n⑥某美容店提供美白、果酸、淡斑、撫紋換膚保養套裝行程\n⑦某車行針對注重休閒的消費者主打跨界休旅房車","options":["①②⑤","①③⑥","②④⑤","②④⑦"],"answer":"D","official":"①使用利益屬於「行為變數」\n②興趣愛好屬於「心理變數」\n③年齡屬於「人口統計變數」\n④社會階層屬於「心理變數」\n⑤品牌忠誠度屬於「行為變數」\n⑥追求商品使用利益屬於「行為變數」\n⑦生活型態屬於「心理變數」"},{"id":"112-5-A-17","exam":"112-5","q":17,"unit":"商業概論","topic":"商業概論","stem":"某半導體大廠憑藉 AI 技術發展浪潮，由公司內部優異研發人員運用晶片伺服器開發自家 ChatGPT，在\n排除洩漏營業祕密的狀況下，使用者能藉此智能對話機器人協助寫程式、翻譯及打報告等，大幅提升工\n作效益。試問此企業運用 SWOT 分析下的何種策略？","options":["增長性策略","扭轉性策略","多元化策略","防禦性策略"],"answer":"A","official":"憑藉 AI 技術發展浪潮→外部機會(O)，由公司內部優\n異研發人員→內部優勢(S)，屬於增長性(SO)策略"},{"id":"112-5-A-18","exam":"112-5","q":18,"unit":"商業概論","topic":"商業概論","stem":"為提升新進歌手的知名度，某藝人經紀公司接下許多商演活動，而新人歌手藉由用心經營社群網站並和\n業者合作，進行產品體驗和宣傳，來賺取額外收入，期能度過「景氣不佳，唱片買氣低迷」的時期。依\n據上述，下列何者錯誤？","options":["此公司賺取佣金為報酬","此新人從事勞務生產","此新人的額外收入可能是商品代言費","「景氣不佳，唱片買氣低迷」為創業風險的經營風險"],"answer":"D","official":"(D)「景氣不佳，唱片買氣低迷」屬於市場風險"},{"id":"112-5-A-19","exam":"112-5","q":19,"unit":"商業概論","topic":"商業概論","stem":"大有和小吳設立有限合夥企業，兩人談好由大有提供資金，小吳提供技術。近期新產品上市後頗受消費\n者好評，兩人討論擴廠計畫，大有提及運用借入資金管道籌資。依據上述，下列何者正確？","options":["小吳屬於普通合夥人，需負擔出資額為限的債務清償責任","此企業可發行公司債募集資金","此企業屬於法人組織","新產品上市時，宜使用「說服性」廣告提醒顧客對產品的需求"],"answer":"C","official":"(A) 小吳屬於普通合夥人，需負擔「無限」清償責任\n(B) 此企業為「有限合夥」，不可發行公司債募集資金\n(C) 此為有限合夥企業，屬於「社團法人」\n(D) 新產品上市時，宜使用「告知性」廣告"},{"id":"112-5-A-20","exam":"112-5","q":20,"unit":"商業概論","topic":"商業概論","stem":"某電視台歌唱節目因積欠多首歌曲版權費用，涉及違法使用「公播權」與「重製權」，有關上述智慧財\n產權的敘述，下列何者正確？","options":["版權屬於著作財產權的一種，因具有創作保護主義，因此只能授權，無法轉讓及共有","其智慧財產權成立的原因在於具識別性","侵犯此智慧財產權須負擔民、刑事責任","著作財產權不須註冊登記，權利受到永久保護"],"answer":"C","official":"(A) 版權屬於著作財產權的一種，可全部或部分授\n權，轉讓及共有\n(B) 智慧財產權成立的原因在於「創作保護主義」，創\n作完成時即受到法律保護\n(D) 著作財產權的權利於著作人存續期間及其死亡後\n50 年受到保護"},{"id":"112-5-A-21","exam":"112-5","q":21,"unit":"商業概論","topic":"商業概論","stem":"文中提及的「速配」、「免運」，屬於柯特勒(Kotler)提出的何種產品層次？","options":["核心產品","期望產品","附加產品","潛在產品"],"answer":"C","official":"「速配」、「免運」皆屬於消費者購買企業有形產品與\n無形服務以外的利益，依照柯特勒的分類，屬於附加\n產品層，又稱引申產品層","group":"112-5-21-25"},{"id":"112-5-A-22","exam":"112-5","q":22,"unit":"商業概論","topic":"商業概論","stem":"文中未提及何種異業結盟的型態？","options":["資訊型結盟","生產製造型結盟","流通型結盟","財務型結盟"],"answer":"A","official":"文中提及的異業結盟型態包括：\n生產製造型結盟→委請上游製造商生產，冠上電商本\n身的品牌(CPLB)銷售\n流通型結盟→臺灣配送請黑貓宅急便負責\n財務型結盟→日本軟銀集團挹注的願景基金\n技術研究發展型結盟→電商龍頭與工研院合作，交流\n物流隱碼技術規格\n未提及分享市場資訊的資訊型結盟","group":"112-5-21-25"},{"id":"112-5-A-23","exam":"112-5","q":23,"unit":"商業概論","topic":"商業概論","stem":"文中提及多元支付方案，符合選擇交易工具的何種考量因素？","options":["安全性","時效性","公開性","便利性"],"answer":"D","official":"(D) 提供多元支付方案能讓消費者方便支付，為便利性","group":"112-5-21-25"},{"id":"112-5-A-24","exam":"112-5","q":24,"unit":"商業概論","topic":"商業概論","stem":"電商在韓國當地的智慧倉儲物流中心，依成立者區分，屬於何種物流中心？","options":["M.D.C","R.D.C","W.D.C","T.D.C"],"answer":"B","official":"(B) 電商屬於網路購物商家，面對最終消費者，故其\n自建的物流中心屬於「零售商型物流中心(R.D.C)」","group":"112-5-21-25"},{"id":"112-5-A-25","exam":"112-5","q":25,"unit":"商業概論","topic":"商業概論","stem":"依據品牌歸屬策略，文中的「CPLB 品牌」屬於何種品牌類別？","options":["製造商品牌","中間商品牌","授權品牌","全國性品牌"],"answer":"B","official":"(B) 委請製造商生產，冠上電商品牌銷售，屬於電商\n自有品牌，又稱中間商品牌","group":"112-5-21-25"}]);
